                    options = mapOf("A" to "In every mathematical model where α is true, β must also be true", "B" to "α is shorter in length than β", "C" to "α and β are completely independent", "D" to "β can be derived only by guessing"),
                    correctOption = "A",
                    explanation = "Entailment is semantic: sentence α entails β if and only if the set of models satisfying α is a subset of the models satisfying β."
                )
            ),
            ragChunks = listOf(
                KnowledgeChunk(
                    chunkId = "AI_CH2_001",
                    subject = "Artificial Intelligence",
                    chapter = "Knowledge Representation & Logic",
                    topic = "First-Order Logic and Resolution Refutation",
                    keywords = listOf("logic", "first order logic", "resolution", "unification", "skolemization", "cnf", "horn clause", "forward chaining"),
                    definition = "First-Order Logic models objects and relations; Resolution Refutation proves statements by asserting the negation and deriving a contradiction.",
                    formulaOrCoreRule = "Entailment: alpha |= beta; Resolution: (A v B) ^ (~B v C) yields (A v C); Implication: P => Q = ~P v Q.",
                    workedExample = "For King(x) ^ Greedy(x) => Evil(x), King(John), Greedy(John), resolution refutation with ~Evil(John) derives the empty clause contradiction.",
                    content = "Knowledge representation and automated logic solvers (Z3 SMT) prove microchip hardware correctness and semantic web biomedical ontologies."
                )
